import argparse
import json
import sys
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
from urllib.parse import urlparse

def validate_config(config):
    if not isinstance(config, dict) or 'sites' not in config:
        return False, "Missing 'sites' key in config"
    sites = config['sites']
    if not isinstance(sites, list):
        return False, "'sites' must be a list"
    for site in sites:
        if not isinstance(site, dict) or 'name' not in site or 'url' not in site:
            return False, f"Missing 'name' or 'url' in site: {site}"
        if not isinstance(site['name'], str) or not isinstance(site['url'], str):
            return False, f"Name and URL must be strings in site: {site}"
    return True, ""

def process_site(site):
    name = site['name']
    url = site['url']
    try:
        response = requests.get(url, timeout=5)
        if 200 <= response.status_code < 300:
            return name, url, str(response.status_code)
        else:
            return name, url, f"HTTP {response.status_code}"
    except requests.exceptions.Timeout:
        return name, url, "timeout"
    except requests.exceptions.RequestException as e:
        return name, url, str(e)

def generate_report(sites, results):
    html = """<!DOCTYPE html>
<html>
<head>
    <title>Site Report</title>
    <style>
        table { border-collapse: collapse; width: 100%; }
        th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
        th { background-color: #f2f2f2; }
    </style>
</head>
<body>
    <h1>Site Report</h1>
    <table>
        <tr>
            <th>Name</th>
            <th>URL</th>
            <th>Result</th>
        </tr>
"""
    for name, url, result in results:
        html += f"""        <tr>
            <td>{name}</td>
            <td>{url}</td>
            <td>{result}</td>
        </tr>
"""
    html += """    </table>
</body>
</html>"""
    with open('report.html', 'w') as f:
        f.write(html)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('config', type=str, help='Path to JSON config file')
    args = parser.parse_args()

    try:
        with open(args.config, 'r') as f:
            config = json.load(f)
    except (IOError, json.JSONDecodeError):
        print("ERROR config: Cannot read or parse config file", file=sys.stderr)
        sys.exit(1)

    valid, message = validate_config(config)
    if not valid:
        print(f"ERROR config: {message}", file=sys.stderr)
        sys.exit(1)

    failed = False
    results = []

    with ThreadPoolExecutor(max_workers=3) as executor:
        futures = {executor.submit(process_site, site): site for site in config['sites']}
        for future in as_completed(futures):
            site = futures[future]
            name, url, result = future.result()
            if result != str(future.result()[2]):  # This is a hack to get the actual result
                results.append((name, url, result))
                if result.startswith("ERROR"):
                    failed = True

    generate_report(config['sites'], results)

    if failed:
        sys.exit(1)
    else:
        sys.exit(0)

if __name__ == "__main__":
    main()
